package hu.boltseged.account;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.math.*; import java.util.*;
@RestController @RequestMapping("/api/admin/accounts") public class AccountController {final AccountRepository repo;final PasswordEncoder enc;AccountController(AccountRepository r,PasswordEncoder e){repo=r;enc=e;}@GetMapping List<AccountView> list(){return repo.findAll().stream().map(AccountView::from).toList();}@PostMapping AccountView create(@Valid @RequestBody AccountRequest x){if(repo.findByEmailIgnoreCase(x.email()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already exists");Account a=new Account(x.companyName(),x.email(),enc.encode(x.password()),"CUSTOMER");a.update(x.companyName(),x.taxNumber(),x.billingAddress(),x.contactName(),x.email(),x.pricingType()==null?"PERCENTAGE":x.pricingType(),x.pricingValue()==null?BigDecimal.ZERO:x.pricingValue());return AccountView.from(repo.save(a));}@PutMapping("/{id}") AccountView update(@PathVariable UUID id,@Valid @RequestBody AccountRequest x){Account a=get(id);a.update(x.companyName(),x.taxNumber(),x.billingAddress(),x.contactName(),x.email(),x.pricingType()==null?"PERCENTAGE":x.pricingType(),x.pricingValue()==null?BigDecimal.ZERO:x.pricingValue());return AccountView.from(repo.save(a));}@PatchMapping("/{id}/active") AccountView active(@PathVariable UUID id,@RequestParam boolean value){Account a=get(id);a.setActive(value);return AccountView.from(repo.save(a));}@PostMapping("/{id}/password") void password(@PathVariable UUID id,@Valid @RequestBody PasswordRequest x){Account a=get(id);a.setPasswordHash(enc.encode(x.password()));repo.save(a);}@GetMapping("/{id}") AccountView one(@PathVariable UUID id){return AccountView.from(get(id));}private Account get(UUID id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}record AccountRequest(String companyName,String taxNumber,String billingAddress,String contactName,@Email @NotBlank String email,@Size(min=12)String password,@Pattern(regexp="PERCENTAGE|FIXED")String pricingType,@PositiveOrZero BigDecimal pricingValue){}record PasswordRequest(@Size(min=12)String password){}record AccountView(UUID id,String companyName,String taxNumber,String billingAddress,String contactName,String email,String pricingType,BigDecimal pricingValue,String role,boolean active){static AccountView from(Account a){return new AccountView(a.getId(),a.getCompanyName(),a.getTaxNumber(),a.getBillingAddress(),a.getContactName(),a.getEmail(),a.getPricingType(),a.getPricingValue(),a.getRole(),a.isActive());}}}
